from pybricks.hubs import PrimeHub
from pybricks.parameters import Button, Direction, Port, Stop
from pybricks.pupdevices import ColorSensor, ForceSensor, Motor
from pybricks.robotics import DriveBase
from pybricks.tools import multitask, run_task, wait

# Set up all devices.
prime_hub = PrimeHub()
color_sensor = ColorSensor(Port.E)
Touch_Sensor = ForceSensor(Port.F)
Left = Motor(Port.A, Direction.COUNTERCLOCKWISE)
Right = Motor(Port.B, Direction.CLOCKWISE)
drive_base = DriveBase(Left, Right, 56, 114)
MM_Left = Motor(Port.C, Direction.CLOCKWISE)
MM_Right = Motor(Port.D, Direction.COUNTERCLOCKWISE)

# Initialize variables.
myWhite = 100
myBlack = 0
targetValue = 50
baseSpeed = 200
turnAmount = 10
mission = 0
max_mission = 3
running = 0

async def Mission_1():
    await wait(0)
    print('Begin Mission 1')
    drive_base.reset(0, 0)
    prime_hub.display.char('A')
    print('Mission A')

async def Mission_2():
    await wait(0)
    drive_base.reset(0, 0)
    prime_hub.display.char('B')
    print('Mission B')

async def Mission_3():
    await wait(0)
    await drive_base.straight(710)
    await Left.run_angle(100, 145)
    await drive_base.straight(35)
    await multitask(
        MM_Left.run_angle(700, 990),
        MM_Right.run_angle(700, 990),
    )
    await multitask(
        MM_Left.run_angle(1000, -800, Stop.BRAKE),
        MM_Right.run_angle(1000, -800, Stop.BRAKE),
    )
    await multitask(
        MM_Left.run_angle(1000, 900, Stop.BRAKE),
        MM_Right.run_angle(1000, 900, Stop.BRAKE),
    )
    await multitask(
        MM_Left.run_angle(2000, -800, Stop.BRAKE),
        MM_Right.run_angle(2000, -800, Stop.BRAKE),
    )
    await multitask(
        MM_Left.run_angle(2000, 900, Stop.BRAKE),
        MM_Right.run_angle(2000, 900, Stop.BRAKE),
    )
    await multitask(
        MM_Left.run_angle(2000, -2000),
        MM_Right.run_angle(2000, -2000),
    )
    await drive_base.straight(-60)
    await Right.run_angle(500, 600)
    await drive_base.straight(250)
    await multitask(
        MM_Left.run_angle(-500, 360),
        MM_Right.run_angle(-500, 360),
    )

async def main():
    global mission, max_mission, running
    mission = 1
    max_mission = 3
    running = 1
    prime_hub.display.off()
    # Hub display turned off. Waiting for Mission Selection
    # Main program runs forever until Center Button is pressed
    while running:
        await wait(0)
        # Scroll LEFT for mission selection
        if Button.LEFT in prime_hub.buttons.pressed():
            # Wait until button is released
            while Button.LEFT in prime_hub.buttons.pressed():
                await wait(0)
            mission = mission - 1
            if mission < 1:
                mission = max_mission
                await wait(200)
            print('Mission:', mission, sep=", ")
            prime_hub.display.number(mission)
        # Scroll RIGHT for mission selection
        if Button.RIGHT in prime_hub.buttons.pressed():
            while Button.RIGHT in prime_hub.buttons.pressed():
                await wait(0)
            mission = mission + 1
            if mission > max_mission:
                mission = 1
                await wait(200)
            print('Mission:', mission, sep=", ")
            prime_hub.display.number(mission)
        # Touch sensor for selecting and running missions
        if await Touch_Sensor.force():
            while await Touch_Sensor.force():
                await wait(0)
            print('Touch Button Released')
            # Showing mission number once again. Display should be showing it already
            prime_hub.display.number(mission)
            if mission == 1:
                print('Calling Mission 1')
                await Mission_1()
            elif mission == 2:
                await Mission_2()
            else:
                await Mission_3()


run_task(main())